import React from "react";
import { useCart } from "./CartContext";
import { Link } from "react-router-dom";

const OrderList = () => {
    const { orders } = useCart();

    if (orders.length === 0) {
        return <p>Chưa có đơn hàng nào.</p>;
    }

    return (
        <div className="container mt-5">
            <h2>Danh Sách Đơn Hàng</h2>
            {orders.map((order) => (
                <div key={order.id} className="order-item mb-4 p-4 border rounded shadow-sm">
                    <h3>Thông tin giao hàng</h3>
                    <p><strong>Ngày đặt:</strong> {order.date}</p>
                    <div>
                        {order.items.map((item, index) => (
                            <div key={index} className="d-flex align-items-center mb-2">
                                <img src={item.image} alt={item.name} className="order-item-image" style={{ width: "50px", height: "50px" }} />
                                <span className="ms-3">{item.name} - {item.price} VND</span>
                            </div>
                        ))}
                    </div>
                    <h4>Tổng giá trị: {order.items.reduce((sum, item) => sum + item.price * item.quantity, 0)} VND</h4>
                </div>
            ))}
        </div>
    );
};

export default OrderList;
